// Пояснение до «;» — текстом, после — плашками; без «;» строка — список, если не похожа на пояснение
// Плашка с «+» впереди — технология, которая у нас уже есть: parse отдаёт имена без «+», а наши — третьим списком.
const list = t => t.split(/,\s|\s·\s/).map(x => x.trim()).filter(Boolean);
function parse(text) {
  const [note, chips] = split(text), have = chips.filter(x => x.startsWith("+")).map(x => x.slice(1));
  return [note, chips.map(x => x.startsWith("+") ? x.slice(1) : x), have];
}
function split(text) {
  const i = text.indexOf(";");
  if (i >= 0) return [text.slice(0, i).trim(), list(text.slice(i + 1))];
  const items = list(text);
  return /(\sв\s|\sна\s|через|есть|заготовка|:|—|«|→|\sи\s|пустая)/.test(text) || (items.length === 1 && text.includes(" ")) ? [text, []] : ["", items];
}
